#!/usr/bin/env node

/**
 * test-poker-share-verifier.js
 *
 * Validates the Chaum-Pedersen primitive and its arbitration-service
 * adapter end-to-end:
 *
 *   1. Round-trip: a real proof generated by proveShareEquality verifies.
 *   2. Tampered A → eq1-mismatch.
 *   3. Tampered B → eq2-mismatch.
 *   4. Tampered z (off by 1) → eq1-mismatch.
 *   5. Wrong Y (proof for a different threshold key) → fails.
 *   6. Wrong D (share doesn't match x) → fails.
 *   7. Wrong C1 (ciphertext substituted) → eq2-mismatch.
 *   8. Arbitration wrapper: well-formed valid proof → claim-refuted.
 *   9. Arbitration wrapper: well-formed but invalid proof → claim-supported.
 *  10. Arbitration wrapper: malformed hex → inconclusive (not a slash).
 *  11. End-to-end through ArbitrationService.setAppEvidenceVerifier.
 */

import sodium from 'sodium-universal'
import b4a from 'b4a'
import {
  verifyShareEquality, proveShareEquality, publicFromSecret, shareFor, baseG,
  POINT_BYTES, SCALAR_BYTES
} from '../packages/core/core/poker/crypto/chaum-pedersen.js'
import { makeInvalidShareVerifier } from '../packages/core/core/poker/crypto/share-verifier.js'
import { ArbitrationService } from '../packages/services/builtin/arbitration-service.js'

let passed = 0
let failed = 0

function assert (condition, label) {
  if (condition) { console.log(`  PASS  ${label}`); passed++ }
  else { console.log(`  FAIL  ${label}`); failed++ }
}

function randomScalar () {
  const s = b4a.alloc(SCALAR_BYTES)
  sodium.crypto_core_ed25519_scalar_random(s)
  return s
}

// Build a "ciphertext" C1: a random point. In a real ElGamal C1 = G^r;
// here we just need any valid curve point that the verifier hasn't seen.
function randomPoint () {
  const r = randomScalar()
  const p = b4a.alloc(POINT_BYTES)
  sodium.crypto_scalarmult_ed25519_base_noclamp(p, r)
  return p
}

function flipBit (buf, bitIndex) {
  const out = b4a.from(buf)
  out[bitIndex >> 3] ^= (1 << (bitIndex & 7))
  return out
}

// ── 1. Round-trip ───────────────────────────────────────────────────────────
function testRoundTrip () {
  console.log('\n── 1. Honest prove + verify round-trip ──')
  const x = randomScalar()
  const Y = publicFromSecret(x)
  const C1 = randomPoint()
  const D = shareFor(x, C1)
  const proof = proveShareEquality({ x, Y, C1, D })
  const v = verifyShareEquality({ Y, C1, D, ...proof })
  assert(v.valid, 'honest proof verifies (' + (v.reason || 'ok') + ')')
}

// ── 2-7. Tamper matrix ──────────────────────────────────────────────────────
function testTamperMatrix () {
  console.log('\n── 2..7. Tamper matrix ──')
  const x = randomScalar()
  const Y = publicFromSecret(x)
  const C1 = randomPoint()
  const D = shareFor(x, C1)
  const proof = proveShareEquality({ x, Y, C1, D })

  // 2. Tamper A
  let v = verifyShareEquality({ Y, C1, D, A: flipBit(proof.A, 7), B: proof.B, z: proof.z })
  // A flipped → e' changes (since e depends on A) AND lhs1 ≠ A + Y^e.
  // Could fail at eq1 or with point-decode if the flipped byte makes it
  // invalid. Either way: not valid.
  assert(!v.valid, 'tampered A → invalid (' + v.reason + ')')

  // 3. Tamper B
  v = verifyShareEquality({ Y, C1, D, A: proof.A, B: flipBit(proof.B, 13), z: proof.z })
  assert(!v.valid, 'tampered B → invalid (' + v.reason + ')')

  // 4. Tamper z (flip lowest bit)
  v = verifyShareEquality({ Y, C1, D, A: proof.A, B: proof.B, z: flipBit(proof.z, 0) })
  assert(!v.valid, 'tampered z → invalid (' + v.reason + ')')

  // 5. Wrong Y (a different threshold key)
  const Y2 = publicFromSecret(randomScalar())
  v = verifyShareEquality({ Y: Y2, C1, D, ...proof })
  assert(!v.valid, 'wrong Y → invalid (' + v.reason + ')')

  // 6. Wrong D (share for a different x)
  const D2 = shareFor(randomScalar(), C1)
  v = verifyShareEquality({ Y, C1, D: D2, ...proof })
  assert(!v.valid, 'wrong D → invalid (' + v.reason + ')')

  // 7. Wrong C1 (different ciphertext)
  const C1b = randomPoint()
  v = verifyShareEquality({ Y, C1: C1b, D, ...proof })
  assert(!v.valid, 'wrong C1 → invalid (' + v.reason + ')')
}

// ── 8, 9, 10. Arbitration wrapper ───────────────────────────────────────────
function testArbitrationWrapper () {
  console.log('\n── 8..10. Arbitration evidence wrapper ──')
  const x = randomScalar()
  const Y = publicFromSecret(x)
  const C1 = randomPoint()
  const D = shareFor(x, C1)
  const proof = proveShareEquality({ x, Y, C1, D })
  const verify = makeInvalidShareVerifier()

  // 8. Well-formed valid proof → claim-refuted (the share is valid, so
  // the claimant's accusation of invalidity is refuted).
  const goodEvidence = {
    tableKey: 'a'.repeat(64),
    handId: 'h',
    cardIndex: 17,
    ciphertext: b4a.toString(C1, 'hex'),
    share: b4a.toString(D, 'hex'),
    witness: {
      Y: b4a.toString(Y, 'hex'),
      proof: {
        A: b4a.toString(proof.A, 'hex'),
        B: b4a.toString(proof.B, 'hex'),
        z: b4a.toString(proof.z, 'hex')
      }
    }
  }
  let r = verify(goodEvidence)
  assert(r.verdict === 'claim-refuted', 'valid proof → claim-refuted (' + r.reason + ')')

  // 9. Tampered proof → claim-supported (share is invalid → claim correct).
  const badEvidence = JSON.parse(JSON.stringify(goodEvidence))
  badEvidence.witness.proof.z = b4a.toString(flipBit(proof.z, 0), 'hex')
  r = verify(badEvidence)
  assert(r.verdict === 'claim-supported', 'tampered z → claim-supported (' + r.reason + ')')

  // 10. Malformed hex → inconclusive (don't slash on procedural errors).
  const broken = JSON.parse(JSON.stringify(goodEvidence))
  broken.witness.Y = 'not-hex'
  r = verify(broken)
  assert(r.verdict === 'inconclusive', 'malformed Y → inconclusive (' + r.reason + ')')

  // Also: missing witness.proof
  const noProof = JSON.parse(JSON.stringify(goodEvidence))
  delete noProof.witness.proof
  r = verify(noProof)
  assert(r.verdict === 'inconclusive', 'missing proof → inconclusive (' + r.reason + ')')

  // Also: wrong-length hex
  const shortZ = JSON.parse(JSON.stringify(goodEvidence))
  shortZ.witness.proof.z = 'aa'
  r = verify(shortZ)
  assert(r.verdict === 'inconclusive', 'short z → inconclusive (' + r.reason + ')')
}

// ── 11. End-to-end through ArbitrationService ──────────────────────────────
async function testEndToEnd () {
  console.log('\n── 11. End-to-end through ArbitrationService ──')
  const svc = new ArbitrationService()
  svc.node = { router: { pubsub: { publish () {} } } }
  svc.setAppEvidenceVerifier('poker/invalid-share', makeInvalidShareVerifier())

  const x = randomScalar()
  const Y = publicFromSecret(x)
  const C1 = randomPoint()
  const D = shareFor(x, C1)
  const proof = proveShareEquality({ x, Y, C1, D })

  // Submit an invalid-share dispute with a VALID proof attached. The
  // verifier will say "share is valid" → claim-refuted.
  const d = await svc.submit({
    type: 'poker/invalid-share',
    respondent: 'b'.repeat(64),
    claimant: 'c'.repeat(64),
    appEvidence: {
      tableKey: 'a'.repeat(64),
      handId: 'h',
      cardIndex: 4,
      ciphertext: b4a.toString(C1, 'hex'),
      share: b4a.toString(D, 'hex'),
      witness: {
        Y: b4a.toString(Y, 'hex'),
        proof: {
          A: b4a.toString(proof.A, 'hex'),
          B: b4a.toString(proof.B, 'hex'),
          z: b4a.toString(proof.z, 'hex')
        }
      }
    },
    penalty: 0
  }, { caller: 'local' })

  const e = await svc.evidence({ id: d.id })
  assert(e.appEvidence && e.appEvidence.verdict === 'claim-refuted',
    'end-to-end: valid proof → claim-refuted (' + (e.appEvidence ? e.appEvidence.reason : 'null') + ')')

  // Now submit with a tampered proof → claim-supported.
  const d2 = await svc.submit({
    type: 'poker/invalid-share',
    respondent: 'b'.repeat(64),
    claimant: 'c'.repeat(64),
    appEvidence: {
      tableKey: 'a'.repeat(64),
      handId: 'h',
      cardIndex: 4,
      ciphertext: b4a.toString(C1, 'hex'),
      share: b4a.toString(D, 'hex'),
      witness: {
        Y: b4a.toString(Y, 'hex'),
        proof: {
          A: b4a.toString(proof.A, 'hex'),
          B: b4a.toString(proof.B, 'hex'),
          z: b4a.toString(flipBit(proof.z, 5), 'hex')
        }
      }
    },
    penalty: 0
  }, { caller: 'local' })

  const e2 = await svc.evidence({ id: d2.id })
  assert(e2.appEvidence && e2.appEvidence.verdict === 'claim-supported',
    'end-to-end: tampered proof → claim-supported (' + (e2.appEvidence ? e2.appEvidence.reason : 'null') + ')')
}

// ── baseG sanity ─────────────────────────────────────────────────────────────
function testBaseG () {
  console.log('\n── 0. baseG returns the standard generator ──')
  const G = baseG()
  assert(G.byteLength === POINT_BYTES, 'baseG is 32 bytes')
  // Idempotent + defensive copy
  const G2 = baseG()
  assert(b4a.equals(G, G2), 'baseG stable across calls')
  G[0] ^= 1
  const G3 = baseG()
  assert(!b4a.equals(G, G3), 'baseG returns a defensive copy (caller mutation does not affect cache)')
}

async function main () {
  testBaseG()
  testRoundTrip()
  testTamperMatrix()
  testArbitrationWrapper()
  await testEndToEnd()
  console.log(`\n── done: ${passed} passed, ${failed} failed ──`)
  process.exit(failed === 0 ? 0 : 1)
}

main().catch((err) => {
  console.error('fatal:', err)
  process.exit(2)
})
